<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Authentication\Domain;

final class ChallengesState
{
    public const VERSION = 1;

    public function __construct(
        public readonly bool $withMfa = false,
        public readonly bool $session = false,
        public readonly ?string $username = null,
        public readonly array $extra = [],
    ) {
    }

    public function withUsername(string $username): self
    {
        return new self(
            withMfa: $this->withMfa,
            session: $this->session,
            username: $username,
            extra: $this->extra
        );
    }

    public function withMfa(bool $withMfa): self
    {
        return new self(
            withMfa: $withMfa,
            session: $this->session,
            username: $this->username,
            extra: $this->extra
        );
    }

    public function withSession(bool $session): self
    {
        return new self(
            withMfa: $this->withMfa,
            session: $session,
            username: $this->username,
            extra: $this->extra
        );
    }

    public static function fromArray(array $data): self
    {
        if (isset($data['v'])) {
            return new self(
                withMfa: (bool) ($data['with_mfa'] ?? false),
                session: (bool) ($data['session'] ?? false),
                username: $data['username'] ?? null,
                extra: is_array($extra = $data['extra'] ?? null) ? $extra : []
            );
        }

        return new self(
            withMfa: (bool) ($data['mfa'] ?? false),
            session: (bool) ($data['session'] ?? false),
            username: $data['username'] ?? null,
            extra: []
        );
    }

    /**
     * @return (array|bool|int|null|string)[]
     *
     * @psalm-return array{v: 1, with_mfa: bool, session: bool, username: null|string, extra: array}
     */
    public function toArray(): array
    {
        return [
            'v' => self::VERSION,
            'with_mfa' => $this->withMfa,
            'session' => $this->session,
            'username' => $this->username,
            'extra' => $this->extra
        ];
    }

}
